def create(name):
 f=unreal.BlueprintFactory();f.set_editor_property('parent_class',unreal.Actor)
 return unreal.load_asset('/Game/QA/'+name) or T.create_asset(name,'/Game/QA',unreal.Blueprint,f)
def build(b,g,name,params=None):
 spec=dict(nodes=g.nodes,links=g.links)
 if params is not None:spec['parameters']=params
 assert unreal.DeliveryEditorLibrary.build_logic_graph(b,name,json.dumps(spec)),name
def save(b):assert E.compile_blueprint(b);assert unreal.EditorAssetLibrary.save_loaded_asset(b,only_if_is_dirty=False)
def var(b,n,typ):
 if n not in [str(x) for x in E.list_member_variable_names(b)]:assert E.add_member_variable(b,n,E.get_basic_type_by_name(typ))
def printvalue(g,id,prefix,source,pin,typ,prev):
 g.call(id+'String','Conv_'+typ+'ToString',STR);g.link(source,pin,id+'String','In'+typ);g.call(id+'Msg','Concat_StrStr',STR,A=prefix);g.link(id+'String','ReturnValue',id+'Msg','B');g.call(id,'PrintString',K,bPrintToScreen='false');g.link(id+'Msg','ReturnValue',id,'InString');g.exec(prev,id);return id
