for i in range(5):
 n='Preset'+str(i);g.call(n,'ChoosePreset'+str(i),WIDGET);g.link('Widget','AsWBP Graphics Settings',n,'self');g.exec(last,n);g.call(n+'Apply','ApplyGraphics',WIDGET);g.link('Widget','AsWBP Graphics Settings',n+'Apply','self');g.exec(n,n+'Apply');g.call(n+'Read','GetViewDistanceQuality',GS);g.link('Settings','ReturnValue',n+'Read','self');g.call(n+'Check','EqualEqual_IntInt',M,B=str(i));g.link(n+'Read','ReturnValue',n+'Check','A')
 g.call(n+'Cvar','GetConsoleVariableFloatValue',K,VariableName='r.ViewDistanceScale');g.exec(n+'Apply',n+'Cvar');g.call(n+'CvarCheck','NearlyEqual_FloatFloat',M,B=str([.3,.5,.75,1,1.25][i]),ErrorTolerance='.001');g.link(n+'Cvar','ReturnValue',n+'CvarCheck','A');g.call(n+'Effective','BooleanAND',M);g.link(n+'Check','ReturnValue',n+'Effective','A');g.link(n+'CvarCheck','ReturnValue',n+'Effective','B');last=printvalue(g,n+'Log','GRAPHICS_PRESET_'+str(i)+'=',n+'Effective','ReturnValue','Bool',n+'Cvar')
g.call('Cycle','CycleShadow',WIDGET);g.link('Widget','AsWBP Graphics Settings','Cycle','self');g.exec(last,'Cycle');g.call('Save','ApplyGraphics',WIDGET);g.link('Widget','AsWBP Graphics Settings','Save','self');g.exec('Cycle','Save');g.call('Reload','LoadSettings',GS,bForceReload='true');g.link('Settings','ReturnValue','Reload','self');g.exec('Save','Reload');g.call('CheckShadow','GetShadowQuality',GS);g.link('Settings','ReturnValue','CheckShadow','self');g.call('IsZero','EqualEqual_IntInt',M,B='0');g.link('CheckShadow','ReturnValue','IsZero','A');last=printvalue(g,'Persistence','GRAPHICS_CUSTOM_PERSISTENCE=','IsZero','ReturnValue','Bool','Reload')
g.call('Minimum','ChoosePreset0',WIDGET);g.link('Widget','AsWBP Graphics Settings','Minimum','self');g.exec(last,'Minimum');g.call('SaveMinimum','ApplyGraphics',WIDGET);g.link('Widget','AsWBP Graphics Settings','SaveMinimum','self');g.exec('Minimum','SaveMinimum');g.call('Show','AddToViewport',U,ZOrder='100');g.link('Create','ReturnValue','Show','self');g.exec('SaveMinimum','Show');g.exec('Show','result');build(b,g,'ReceiveBeginPlay');var(b,'Age','real');var(b,'Stage','int');save(b)
g=d.Graph();g.get('Age');g.get('Stage');g.call('Plus','Add_DoubleDouble',M);g.link('Age','Age','Plus','A');g.link('entry','DeltaSeconds','Plus','B');g.setter('Clock','Age','Plus');g.exec('entry','Clock');g.call('Done','Greater_DoubleDouble',M,B='12');g.link('Age','Age','Done','A');g.branch('QuitNow','Done');g.exec('Clock','QuitNow');g.call('Quit','ExecuteConsoleCommand',K,Command='quit');g.exec('QuitNow','Quit');g.exec('QuitNow','result','else');g.exec('Quit','result');build(b,g,'ReceiveTick');save(b)
unreal.EditorLoadingAndSavingUtils.new_blank_map(False);actors=unreal.get_editor_subsystem(unreal.EditorActorSubsystem);actors.spawn_actor_from_class(b.generated_class(),unreal.Vector());world=unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem).get_editor_world();world.get_world_settings().set_editor_property('default_game_mode',unreal.GameModeBase);assert unreal.EditorLoadingAndSavingUtils.save_map(world,'/Game/QA/GraphicsSettingsQA')
