g.links.remove(['Settings','then','Quality','execute'])
g.call('CommandLine','GetCommandLine',K);g.call('QualityOption','Split',STR,InStr='-BogotaQuality=',SearchCase='IgnoreCase',SearchDir='FromStart');g.link('CommandLine','ReturnValue','QualityOption','SourceString');g.call('ParsedQuality','Conv_StringToInt',STR);g.link('QualityOption','RightS','ParsedQuality','InString');g.call('QualityRange','Clamp',M,Min='0',Max='4');g.link('ParsedQuality','ReturnValue','QualityRange','Value');g.setter('RememberPreset','Preset','QualityRange');g.exec('Settings','RememberPreset');g.exec('RememberPreset','Quality');build(b,g,'ReceiveBeginPlay');save(b)
for n,typ in [('Age','real'),('CaptureAge','real'),('Stage','int')]:var(b,n,typ)
save(b);g=d.Graph();g.get('Age');g.get('Stage');g.call('Plus','Add_DoubleDouble',M);g.link('Age','Age','Plus','A');g.link('entry','DeltaSeconds','Plus','B');g.setter('Clock','Age','Plus');g.exec('entry','Clock');g.call('Warm','Greater_DoubleDouble',M,B='15');g.link('Age','Age','Warm','A');g.call('NotStarted','EqualEqual_IntInt',M,B='0');g.link('Stage','Stage','NotStarted','A');g.call('Ready','BooleanAND',M);g.link('Warm','ReturnValue','Ready','A');g.link('NotStarted','ReturnValue','Ready','B');g.branch('Start','Ready');g.exec('Clock','Start');g.call('CSV','ExecuteConsoleCommand',K,Command='csvprofile start');g.exec('Start','CSV');g.setter('Marked','Stage',value='1');g.exec('CSV','Marked');g.exec('Marked','result');g.call('StopTime','Greater_DoubleDouble',M,B='75');g.link('Age','Age','StopTime','A');g.call('Capturing','EqualEqual_IntInt',M,B='1');g.link('Stage','Stage','Capturing','A');g.call('StopReady','BooleanAND',M);g.link('StopTime','ReturnValue','StopReady','A');g.link('Capturing','ReturnValue','StopReady','B');g.branch('Stop','StopReady');g.exec('Start','Stop','else');g.call('CSVStop','ExecuteConsoleCommand',K,Command='csvprofile stop');g.exec('Stop','CSVStop');g.setter('Stopped','Stage',value='2');g.exec('CSVStop','Stopped');g.exec('Stopped','result');g.call('QuitTime','Greater_DoubleDouble',M,B='80');g.link('Age','Age','QuitTime','A');g.branch('Exit','QuitTime');g.exec('Stop','Exit','else');g.call('Quit','ExecuteConsoleCommand',K,Command='quit');g.exec('Exit','Quit');g.exec('Quit','result');g.exec('Exit','result','else');build(b,g,'ReceiveTick');save(b)
# Begin measurement after initial PSO/navigation work, then capture a full minute.
g.get('CaptureAge');g.links.remove(['Clock','then','Start','execute'])
g.call('Running','Greater_IntInt',M,B='0');g.link('Stage','Stage','Running','A');g.branch('AdvanceCapture','Running');g.exec('Clock','AdvanceCapture');g.call('CapturePlus','Add_DoubleDouble',M);g.link('CaptureAge','CaptureAge','CapturePlus','A');g.link('entry','DeltaSeconds','CapturePlus','B');g.setter('CaptureClock','CaptureAge','CapturePlus');g.exec('AdvanceCapture','CaptureClock');g.exec('CaptureClock','Start');g.exec('AdvanceCapture','Start','else')
g.call('PSOs','NumPrecompilingPSOsRemaining','/Script/Engine.KismetRenderingLibrary');g.call('ShadersReady','EqualEqual_IntInt',M,B='0');g.link('PSOs','ReturnValue','ShadersReady','A');g.call('BuildingNav','IsNavigationBeingBuilt','/Script/NavigationSystem.NavigationSystemV1');g.call('NavReady','Not_PreBool',M);g.link('BuildingNav','ReturnValue','NavReady','A');g.call('Prepared','BooleanAND',M);g.link('ShadersReady','ReturnValue','Prepared','A');g.link('NavReady','ReturnValue','Prepared','B');g.call('StartReady','BooleanAND',M);g.link('Ready','ReturnValue','StartReady','A');g.link('Prepared','ReturnValue','StartReady','B');g.links.remove(['Ready','ReturnValue','Start','Condition']);g.link('StartReady','ReturnValue','Start','Condition')
for link in g.links:
 if link[2] in ['StopTime','QuitTime'] and link[3]=='A':link[0]='CaptureAge';link[1]='CaptureAge'
